  const salida = registros.slice();
  for (let i = 1; i < salida.length; i++) {
    const actual = salida[i];
    let j = i;
    while (j > 0 && salida[j - 1][0] < actual[0]) {
      salida[j] = salida[j - 1];
      j--;
    }
    salida[j] = actual;
  }
  return salida;
}
